import Foundation
import Network

/// Demo-only HTTP fixture. Bound to loopback; never included in the library product.
/// Supports the fixed Content-Length requests generated by this example, not a general HTTP server.
final class FLSDemoServer: Sendable {
    private let listener: NWListener
    private let queue = DispatchQueue(label: "FLSNetworkingDemo.server")

    init() throws {
        let parameters = NWParameters.tcp
        parameters.requiredLocalEndpoint = .hostPort(host: "127.0.0.1", port: .any)
        listener = try NWListener(using: parameters)
    }

    func start() async throws -> URL {
        let ready = AsyncStream.makeStream(of: URL.self)
        listener.stateUpdateHandler = { [weak self] state in
            switch state {
            case .ready:
                if let port = self?.listener.port,
                   let url = URL(string: "http://127.0.0.1:\(port.rawValue)") {
                    ready.continuation.yield(url)
                }
                ready.continuation.finish()
            case .failed, .cancelled:
                ready.continuation.finish()
            default: break
            }
        }
        listener.newConnectionHandler = { [weak self] connection in
            guard let self else { connection.cancel(); return }
            connection.start(queue: queue)
            receive(connection, buffer: Data())
        }
        listener.start(queue: queue)
        return try await withTaskCancellationHandler {
            for await url in ready.stream {
                try Task.checkCancellation()
                return url
            }
            try Task.checkCancellation()
            throw URLError(.cannotConnectToHost)
        } onCancel: {
            self.stop()
        }
    }

    func stop() { listener.cancel() }

    deinit { listener.cancel() }

    private func receive(_ connection: NWConnection, buffer: Data) {
        connection.receive(minimumIncompleteLength: 1, maximumLength: 65_536) { [weak self] data, _, complete, error in
            guard let self else { connection.cancel(); return }
            var buffer = buffer
            buffer.append(data ?? Data())
            guard error == nil, buffer.count <= 2_097_152 else { connection.cancel(); return }
            guard let boundary = buffer.range(of: Data("\r\n\r\n".utf8)) else {
                if complete || buffer.count > 65_536 { connection.cancel() }
                else { receive(connection, buffer: buffer) }
                return
            }
            let headers = String(decoding: buffer[..<boundary.lowerBound], as: UTF8.self)
                .components(separatedBy: "\r\n")
            let contentLength = headers.dropFirst().first { $0.lowercased().hasPrefix("content-length:") }
                .flatMap { Int($0.dropFirst("content-length:".count).trimmingCharacters(in: .whitespaces)) } ?? 0
            guard (0...1_048_576).contains(contentLength) else { connection.cancel(); return }
            guard buffer.count - boundary.upperBound >= contentLength else {
                if complete { connection.cancel() }
                else { receive(connection, buffer: buffer) }
                return
            }
            let requestLine = (headers.first ?? "").split(separator: " ")
            guard requestLine.count == 3 else { connection.cancel(); return }
            let path = String(requestLine[1]).split(separator: "?", maxSplits: 1).first.map(String.init) ?? ""
            let body = Data(buffer[boundary.upperBound..<(boundary.upperBound + contentLength)])
            let response = response(path: path, body: body)
            if path == "/slow" {
                queue.asyncAfter(deadline: .now() + 10) { [weak self] in
                    guard let self else { connection.cancel(); return }
                    send(response, over: connection)
                }
            } else {
                send(response, over: connection)
            }
        }
    }

    private func response(path: String, body: Data) -> FLSDemoServerResponse {
        switch path {
        case "/get", "/slow":
            return json(["method": "GET", "message": "Hello FLSNetworking"])
        case "/post":
            let value = (try? JSONSerialization.jsonObject(with: body)) as? [String: String]
            return json(["method": "POST", "message": value?["message"] ?? "", "receivedBytes": body.count])
        case "/payload":
            return json(["code": 0, "message": "ok", "data": ["method": "GET", "message": "业务数据解析成功"]])
        case "/upload":
            return json(["method": "PUT", "message": "file received", "receivedBytes": body.count])
        case "/file":
            return FLSDemoServerResponse(status: 200, contentType: "application/octet-stream",
                                         body: Data(repeating: 0x46, count: 262_144))
        case "/status/503":
            return json(["message": "演示服务暂时不可用"], status: 503)
        case "/business-error":
            return json(["code": 401, "msg": "演示业务错误", "data": NSNull()])
        default:
            return json(["message": "unknown demo route"], status: 404)
        }
    }

    private func json(_ value: [String: Any], status: Int = 200) -> FLSDemoServerResponse {
        // All values above are fixed JSON-compatible fixtures.
        let body = (try? JSONSerialization.data(withJSONObject: value, options: [.sortedKeys])) ?? Data()
        return FLSDemoServerResponse(status: status, contentType: "application/json; charset=utf-8", body: body)
    }

    private func send(_ response: FLSDemoServerResponse, over connection: NWConnection) {
        let headers = "HTTP/1.1 \(response.status) Demo\r\nContent-Type: \(response.contentType)\r\nContent-Length: \(response.body.count)\r\nConnection: close\r\n\r\n"
        var bytes = Data(headers.utf8)
        bytes.append(response.body)
        connection.send(content: bytes, completion: .contentProcessed { _ in connection.cancel() })
    }
}

private struct FLSDemoServerResponse: Sendable {
    let status: Int
    let contentType: String
    let body: Data
}
